names = ["toolbox", "red toolbox", "tool box", "hammer", "screwdriver", "wrench", "pliers"]
poses = {}
for name in names:
    r = primitives.call(name='submit_capx_action', action='get_object_pose', native_api=True, parameters={'object_name':name,'return_bbox_extent':True})
    if r.ok and r.output is not None:
        poses[name] = r.output
        print(name, "FOUND")
    else:
        print(name, "not found")
print("count", len(poses))
for name in ["toolbox", "red toolbox", "hammer", "screwdriver", "wrench", "pliers"]:
    r = primitives.call(name='submit_capx_action', action='sample_grasp_pose', native_api=True, parameters={'object_name':name})
    print("grasp", name, r.ok, r.output is not None if r.ok else False)
    if r.ok and r.output is not None:
        print(name, r.output)

def call(action, parameters):
    r = primitives.call(name='submit_capx_action', action=action, native_api=True, parameters=parameters)
    if not r.ok:
        print(action, "failed", r.output)
        return None
    return r.output.get('native_api_result')
def values(v):
    if isinstance(v, dict) and 'values' in v:
        return v['values']
    return v
for n in ['red toolbox','hammer','screwdriver','wrench','pliers']:
    data = poses[n]['native_api_result'] if n in poses else None
    if data:
        print(n, [values(v) for v in data[:3]])
print("robot",call('get_robot_position',{}))
r = call('navigate_to_pose', {'pose_2d':[22.8,-0.65,3.14159]})
print("navigate",r)

